import React, { useState, useEffect } from 'react';
import './Usuarios.css'; // Estilos personalizados

function Usuarios() {
  const [users, setUsers] = useState([]);
  const [search, setSearch] = useState('');
  const [selectedUser, setSelectedUser] = useState(null);
  const [editMode, setEditMode] = useState(false);
  const [showConfirmModal, setShowConfirmModal] = useState(false);
  const [userToDelete, setUserToDelete] = useState(null);

  // Efecto para cargar los usuarios
  useEffect(() => {
    const fetchUsers = async () => {
      try {
        const token = localStorage.getItem('token');

        if (!token) {
          console.error('Token no proporcionado');
          return;
        }

        const response = await fetch('http://localhost:4000/api/user/allusers', {
          method: 'GET',
          headers: {
            'Authorization': `Bearer ${token}`,
            'Content-Type': 'application/json',
          },
        });

        const data = await response.json();
        const transformedUsers = data.map(user => ({
          id: user.id_usuario,
          nombre: user.nombre,
          apellido: user.apellido,
          email: user.email,
          role: user.id_rol === 1 ? 'usuario' : 'administrador',
        }));

        setUsers(transformedUsers);
      } catch (error) {
        console.error('Error fetching users:', error);
      }
    };

    fetchUsers();
  }, []);

  const filteredUsers = users.filter(user =>
    `${user.nombre} ${user.apellido} ${user.email}`.toLowerCase().includes(search.toLowerCase())
  );

  // Función para eliminar usuario
  const handleDeleteUser = async () => {
    try {
      const token = localStorage.getItem('token');
      if (!token) {
        console.error('Token no proporcionado');
        return;
      }

      const response = await fetch(`http://localhost:4000/api/user/delete/${userToDelete.id}`, {
        method: 'DELETE',
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json',
        },
      });

      if (response.ok) {
        setUsers(users.filter(user => user.id !== userToDelete.id));
        console.log('Usuario eliminado');
      } else {
        console.error('Error al eliminar el usuario:', response.statusText);
      }
    } catch (error) {
      console.error('Error al eliminar el usuario:', error);
    }

    setShowConfirmModal(false);  // Cerrar el modal de confirmación
    setUserToDelete(null);  // Resetear el usuario a eliminar
  };

  // Mostrar el modal de confirmación antes de eliminar
  const confirmDelete = (user) => {
    setUserToDelete(user); // Establecer el usuario que se eliminará
    setShowConfirmModal(true); // Mostrar el modal de confirmación
  };

  // Cancelar la eliminación y cerrar el modal
  const cancelDelete = () => {
    setShowConfirmModal(false);
    setUserToDelete(null);
  };

  const handleView = (user) => {
    setSelectedUser(user);
    setEditMode(false);
  };

  const handleEdit = (user) => {
    setSelectedUser({ ...user });
    setEditMode(true);  // Activar el modo de edición
  };

  const handleSave = () => {
    setUsers(users.map(u => (u.id === selectedUser.id ? selectedUser : u)));
    setSelectedUser(null); // Limpiar el usuario seleccionado después de guardar
    setEditMode(false); // Salir del modo edición
  };

  const closeModal = () => {
    setSelectedUser(null);
    setEditMode(false);
  };

  return (
    <div className="usuarios-container">
      <h1>Gestión de Usuarios</h1>

      <div className="search-bar">
        <input
          type="text"
          placeholder="Buscar por nombre, apellido o email..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
        <button>🔍</button>
      </div>

      <table className="user-table">
        <thead>
          <tr>
            <th>Nombre</th>
            <th>Apellido</th>
            <th>Email</th>
            <th>Rol</th>
            <th>Acciones</th>
          </tr>
        </thead>
        <tbody>
          {filteredUsers.map(user => (
            <tr key={user.id}>
              <td>{user.nombre}</td>
              <td>{user.apellido}</td>
              <td>{user.email}</td>
              <td>{user.role}</td>
              <td>
                <button onClick={() => handleView(user)}>Ver</button>
                <button onClick={() => handleEdit(user)}>Modificar</button>
                <button onClick={() => confirmDelete(user)}>Dar de baja</button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>

      {/* Modal de confirmación */}
      {showConfirmModal && (
        <div className="modal-overlay">
          <div className="modal">
            <span className="close" onClick={cancelDelete}>&times;</span>
            <h2>¿Estás seguro de que deseas eliminar este usuario?</h2>
            <p>{userToDelete?.nombre} {userToDelete?.apellido}</p>
            <div className="modal-buttons">
              <button className="modal-btn confirm" onClick={handleDeleteUser}>Sí, eliminar</button>
              <button className="modal-btn cancel" onClick={cancelDelete}>Cancelar</button>
            </div>
          </div>
        </div>
      )}

      {/* Modal para editar */}
      {selectedUser && (
      <div className="modal-overlay">
        <div className="modal">
          <span className="close" onClick={closeModal}>&times;</span>
          <h2>{editMode ? 'Modificar Usuario' : 'Información del Usuario'}</h2>
          <form onSubmit={(e) => { e.preventDefault(); handleSave(); }}>
            <label>Nombre:</label>
            <input
              type="text"
              value={selectedUser.nombre}
              onChange={(e) => setSelectedUser({ ...selectedUser, nombre: e.target.value })}
              disabled={!editMode}
            />

            <label>Apellido:</label>
            <input
              type="text"
              value={selectedUser.apellido}
              onChange={(e) => setSelectedUser({ ...selectedUser, apellido: e.target.value })}
              disabled={!editMode}
            />

            <label>DNI:</label>
            <input
              type="text"
              value={selectedUser.dni}
              onChange={(e) => setSelectedUser({ ...selectedUser, dni: e.target.value })}
              disabled={!editMode}
            />

            <label>Email:</label>
            <input
              type="email"
              value={selectedUser.email}
              onChange={(e) => setSelectedUser({ ...selectedUser, email: e.target.value })}
              disabled={!editMode}
            />

            <label>Número de celular:</label>
            <input
              type="text"
              value={selectedUser.nro_celular}
              onChange={(e) => setSelectedUser({ ...selectedUser, nro_celular: e.target.value })}
              disabled={!editMode}
            />

            <label>Rol:</label>
            <select
              value={selectedUser.role}
              onChange={(e) => setSelectedUser({ ...selectedUser, role: e.target.value })}
              disabled={!editMode}
            >
              <option value="usuario">usuario</option>
              <option value="administrador">administrador</option>
            </select>


            {/* Campo de dirección */}
            <label>Dirección:</label>
            <input
              type="text"
              value={selectedUser.direccion || ''}
              onChange={(e) => setSelectedUser({ ...selectedUser, direccion: e.target.value })}
              disabled={!editMode}
            />

            {editMode && <button type="submit" className="save-btn">Guardar</button>}
          </form>
        </div>
      </div>
    )}

    </div>
  );
}

export default Usuarios;
